mise () 
{ 
    local command;
    command="${1:-}";
    if [ "$#" = 0 ]; then
        command /home/khoi/.local/bin/mise;
        return;
    fi;
    shift;
    case "$command" in 
        deactivate | shell | sh)
            if [[ ! " $* " =~ " --help " ]] && [[ ! " $* " =~ " -h " ]]; then
                eval "$(command /home/khoi/.local/bin/mise "$command" "$@")";
                return $?;
            fi
        ;;
    esac;
    command /home/khoi/.local/bin/mise "$command" "$@"
}

cd () 
{ 
    __zsh_like_cd cd "$@"
}

__zsh_like_cd () 
{ 
    \typeset __zsh_like_cd_hook;
    if builtin "$@"; then
        for __zsh_like_cd_hook in chpwd ${chpwd_functions[@]+"${chpwd_functions[@]}"};
        do
            if \typeset -f "$__zsh_like_cd_hook" > /dev/null 2>&1; then
                "$__zsh_like_cd_hook" || break;
            fi;
        done;
        true;
    else
        return $?;
    fi
}

