"""Parsers for an agent's JSON event stream: spend, tool calls, and failure text."""

from __future__ import annotations

import json
from collections.abc import Callable
from typing import Any


def _jsonl(events: str) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for line in events.splitlines():
        try:
            out.append(json.loads(line))
        except ValueError:
            continue
    return out


def measure(events: str) -> dict[str, Any]:
    """Tokens, steps and tool calls from opencode's JSON event stream."""
    tokens = {"input": 0, "output": 0, "cache_read": 0, "cache_write": 0}
    calls: dict[str, int] = {}
    steps = 0
    for line in events.splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        part = event.get("part", {})
        if event.get("type") == "tool_use":
            calls[part.get("tool", "?")] = calls.get(part.get("tool", "?"), 0) + 1
        elif event.get("type") == "step_finish":
            steps += 1
            used = part.get("tokens", {})
            tokens["input"] += used.get("input", 0)
            tokens["output"] += used.get("output", 0) + used.get("reasoning", 0)
            tokens["cache_read"] += used.get("cache", {}).get("read", 0)
            tokens["cache_write"] += used.get("cache", {}).get("write", 0)
    return {"tokens": tokens, "steps": steps, "calls": calls}


def agent_error(events: str) -> str | None:
    for line in events.splitlines():
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if event.get("type") == "error":
            error = event.get("error", {})
            return f"{error.get('type', 'agent error')}: {error.get('message', '')}"
    return None


def agent_failure(
    status: str, events: str, error: Callable[[str], str | None] = agent_error
) -> str | None:
    if message := error(events):
        return message
    return f"agent exited with {status}" if status not in {"ok", "timeout"} else None

def require() -> None:
    """Fail closed before any run starts: without bubblewrap nothing is confined."""
    if shutil.which("bwrap") is None:
        raise SystemExit("bubblewrap (bwrap) is required: agent runs are confined, not trusted")


def clean_env(extra: Mapping[str, str]) -> dict[str, str]:
    """The allowlisted host variables, then ``extra``."""
    return {k: v for k in KEEP_ENV if (v := os.environ.get(k))} | dict(extra)


def secret_hides() -> list[Path]:
    return [p for name in SECRET_PATHS if (p := Path.home() / name).exists()]


def confine(
    argv: Iterable[str | Path], *, writable: Path, hide: Iterable[Path], net: bool
) -> list[str]:
    """``argv`` under bubblewrap: the host read-only, ``/run`` and ``/var/run`` replaced (a
    read-only bind still allows ``connect()`` to their sockets), ``/tmp`` and every ``hide``
    path replaced by an empty tmpfs (a file by ``/dev/null``), ``writable`` the only writable
    path. Name-service files that lived under those dirs are bound back, or the run is refused.
    ``net=False`` also cuts the network. Mounts apply in order, so ``writable`` is bound last
    and stays visible when it lives under a hidden directory."""
    require()
    command = [
        "bwrap",
        "--ro-bind",
        "/",
        "/",
        "--dev",
        "/dev",
        "--proc",
        "/proc",
        "--tmpfs",
        "/tmp",
        *socket_mounts(runtime_dirs(), _NAME_SERVICE),
    ]
    for path in (p for p in hide if p.exists()):
        if path.is_file():
            command += ["--ro-bind", "/dev/null", str(path)]
        else:
            command += ["--tmpfs", str(path)]
    command += ["--bind", str(writable), str(writable), "--die-with-parent", "--unshare-pid"]
    if not net:
        command.append("--unshare-net")
    return [*command, *map(str, argv)]


def secret_values(node: Any) -> list[str]:
    """Every string at least 12 characters long in a parsed credential document."""
    if isinstance(node, str):
        return [node] if len(node) >= 12 else []
    if isinstance(node, dict):
        return [s for value in node.values() for s in secret_values(value)]
    if isinstance(node, list):
        return [s for value in node for s in secret_values(value)]
    return []


def redact(text: str, secrets: Iterable[str]) -> str:
    """``text`` with each secret replaced. Traces are kept, so a credential a run printed must not
    reach them."""
    for secret in sorted(secrets, key=len, reverse=True):
        text = text.replace(secret, "[redacted]")
    return text


def json_secrets(path: Path) -> list[str]:
    return secret_values(json.loads(path.read_text(encoding="utf-8")))

"""Confinement of git and traces on the agent's tree, and the hidden-test score."""

from __future__ import annotations

import os
import re
import subprocess
from collections.abc import Callable
from pathlib import Path
from typing import Any

import arms
import confine
import tasks

# Hooks and fsmonitor off. Filters still run, so git_on_agent confines every command on this tree.
GIT_SAFE = ("-c", "core.fsmonitor=false", "-c", "core.hooksPath=/dev/null")


def git_on_agent(base: Path, *args: str, cwd: Path) -> subprocess.CompletedProcess[str]:
    """Git on the agent's tree, confined. Its clean and smudge filters must not run on the host."""
    import run

    argv = confine.confine(["git", *GIT_SAFE, *args], writable=base, hide=run.hidden(), net=False)
    return tasks.sh(*argv, cwd=cwd)


def write_private(path: Path, text: str) -> None:
    """Replace ``path`` with a new regular file. The agent can plant a symlink or hardlink
    here; following it would truncate a host file."""
    try:
        path.unlink()
    except FileNotFoundError:
        pass
    except IsADirectoryError:
        raise RuntimeError(f"trace path is a directory: {path}") from None
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    flags |= getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(path, flags, 0o644)
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        handle.write(text)


def confined(base: Path, net: bool) -> Callable[[list[str]], list[str]]:
    def wrap(argv: list[str]) -> list[str]:
        import run

        return confine.confine(argv, writable=base, hide=run.hidden(), net=net)

    return wrap


def isolation(arm: str, base: Path) -> None:
    """Reject runs that loaded MCPs other than the one explicitly configured for the arm."""
    log = "\n".join(
        p.read_text(encoding="utf-8", errors="replace")
        for p in (base / "data" / "opencode" / "log").glob("*.log")
    )
    seen = set(re.findall(r'message="mcp connected" server=(\S+)', log))
    expected = {"oxide"} if arm in arms.OXIDE_ARMS else set()
    if seen != expected:
        raise RuntimeError(f"isolation: unexpected MCP servers {sorted(seen)}")


def score(task: dict[str, Any], work: Path, env: dict[str, str], base: Path) -> dict[str, Any]:
    """Hidden tests on the agent's tree; its own test edits are reverted first.
    An id the run did not report is a failed test. ``tasks.TestRunError`` is infrastructure
    and propagates, so the caller records a harness error rather than an unresolved task."""
    for path in task["test_files"]:
        listed = git_on_agent(base, "cat-file", "-e", f"HEAD:{path}", cwd=work)
        if listed.returncode == 0:
            git_on_agent(base, "checkout", "HEAD", "--", path, cwd=work)
        else:
            # rm, confined: a planted symlinked parent must not redirect the delete onto the host.
            tasks.sh(*confined(base, net=False)(["rm", "-f", "--", path]), cwd=work)
    tasks.apply(work, task["test_patch"], wrap=confined(base, net=False), scratch=base)
    outcome = tasks.tests(
        work, env, task["test_files"], wrap=confined(base, net=False), agent_tree=True
    )
    failed = [t for t in task["fail_to_pass"] if outcome.get(t) != "PASSED"]
    broken = [t for t in task["pass_to_pass"] if outcome.get(t) != "PASSED"]
    return {
        "resolved": not failed and not broken,
        "f2p_failed": len(failed),
        "p2p_broken": len(broken),
    }


def connected(data: Path, arm: str) -> int:
    """How many OXIDE tools OpenCode connected in this run, from its log. A run that never calls
    the tool with this count at 1 has ignored a connected tool, which is a different finding from
    one where the tool never reached the agent."""
    log = data / "opencode" / "log" / "opencode.log"
    if arm not in arms.OXIDE_ARMS or not log.exists():
        return 0
    counts = [
        int(m.group(1))
        for line in log.read_text(encoding="utf-8", errors="replace").splitlines()
        if "mcp connected" in line and "server=oxide" in line
        if (m := re.search(r"tools=(\d+)", line))
    ]
    return max(counts, default=0)

"""Protocol guards for the paired agent evaluation: what a results file is bound to, how much
it may spend, and how often a held-out task set may be opened.

Pure functions only, so the rules are tested without running an agent.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

PROTOCOL = "agent-swe-v2"


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def spend(tokens: dict[str, int]) -> int:
    """Tokens billed for one run, unweighted: every input, output and cache token. Prices vary
    by provider and cache tier, so the cap is in tokens; USD is the token counts times a price
    the operator applies to the recorded counts."""
    return sum(tokens.get(k, 0) for k in ("input", "output", "cache_read", "cache_write"))


def row_has_spend(row: dict[str, Any]) -> bool:
    return "spend" in row or isinstance(row.get("tokens"), dict)


def row_spend(row: dict[str, Any]) -> int:
    """A recorded run's spend: the stored figure, or its tokens for rows written before it."""
    if "spend" in row:
        return int(row["spend"])
    return spend(row["tokens"]) if isinstance(row.get("tokens"), dict) else 0


def spent(rows: list[dict[str, Any]]) -> int:
    return sum(row_spend(r) for r in rows)


def admit(spent_so_far: int, in_flight: int, observed_max: int | None, cap: int | None) -> bool:
    """Whether one more run may start under the token cap.

    Before any run has reported its spend there is nothing to project from, so one run at a
    time calibrates the cost. After that a run starts only if the spend so far plus every
    in-flight run and this one, each at the largest observed run cost, still fits the cap.
    A start-time check alone let a first wave of parallel runs overshoot a cap ~1.8x."""
    if cap is None:
        return True
    if observed_max is None:
        return in_flight == 0 and spent_so_far < cap
    return spent_so_far + (in_flight + 1) * observed_max <= cap


def check_manifest(path: Path, manifest: dict[str, Any]) -> None:
    """Write the manifest beside a new results file, or refuse to resume under a different one.

    A results file is only comparable to runs made under the same tasks, code, prompt, arm
    configuration and agent binary. Resuming under a changed protocol mixes two experiments."""
    if not path.exists():
        path.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        return
    recorded = json.loads(path.read_text(encoding="utf-8"))
    diff = sorted(k for k in set(recorded) | set(manifest) if recorded.get(k) != manifest.get(k))
    if diff:
        raise SystemExit(
            f"{path} was recorded under a different protocol ({', '.join(diff)} changed); "
            "start a new results file instead of resuming"
        )


def heldout_open(log: Path, tasks_sha: str, out: Path) -> None:
    """A held-out task set is opened once. Resuming the same results file is allowed; a second
    file on the same set is a second look, which the protocol forbids."""
    entries = [json.loads(line) for line in log.read_text().splitlines()] if log.exists() else []
    for entry in entries:
        if entry["tasks_sha256"] == tasks_sha and entry["out"] != str(out):
            raise SystemExit(
                f"held-out tasks {tasks_sha[:12]} were already opened by {entry['out']}; "
                "a held-out set is one look, so write a new held-out set instead"
            )
    if not any(e["tasks_sha256"] == tasks_sha and e["out"] == str(out) for e in entries):
        with log.open("a", encoding="utf-8") as file:
            file.write(json.dumps({"tasks_sha256": tasks_sha, "out": str(out)}) + "\n")

